#include <stdio.h>
#include <string.h>

int main(void) {
    char numero[1005], palavra[1005];
    int m, total = 0;

    if (scanf("%1000s", numero) != 1) return 0;
    if (scanf("%d", &m) != 1) return 0;

    for (int i = 0; i < m; i++) {
        scanf("%1000s", palavra);

        if (strlen(numero) != strlen(palavra)) continue;

        int corresponde = 1;
        for (int j = 0; palavra[j] != '\0'; j++) {
            char c = palavra[j];
            char digito;

            if (c >= 'a' && c <= 'c') digito = '2';
            else if (c >= 'd' && c <= 'f') digito = '3';
            else if (c >= 'g' && c <= 'i') digito = '4';
            else if (c >= 'j' && c <= 'l') digito = '5';
            else if (c >= 'm' && c <= 'o') digito = '6';
            else if (c >= 'p' && c <= 's') digito = '7';
            else if (c >= 't' && c <= 'v') digito = '8';
            else digito = '9';

            if (digito != numero[j]) {
                corresponde = 0;
                break;
            }
        }

        if (corresponde) total++;
    }

    printf("%d\n", total);
    return 0;
}
